(function () {
'use strict';
const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const electiveTitles = ['Tratamiento','Procedimiento','Riesgo trombótico','Datos clínicos','Plan perioperatorio'];
const electiveSubtitles = ['Fármaco y contexto','Intervención y sangrado','Motivo de anticoagulación','Función renal e INR','Decisión y cronología'];
const labels = {minimal:'Mínimo',low:'Bajo',moderate:'Moderado',lowModerate:'Bajo-moderado',high:'Alto',unknown:'Sin determinar'};
const indicationLabels = {af:'Fibrilación auricular',valve:'Prótesis valvular',vte:'Tromboembolia venosa',other:'Otras indicaciones'};
const fresh = () => ({...QXUrgent.fresh(),...Object.fromEntries(QXClinical.requiredBooleanFields.map(key=>[key,false])),drug:'',urgency:'',urgent:false,indication:'',procedureId:'',specialty:'',query:'',bleedingRisk:'',age:'',sex:'',strokeMonths:'',vteMonths:'',thrombophilia:'none',crcl:'',inr:'',procedureDate:'',riskConfirmed:false,clinicalConfirmed:false});
let state = fresh(), step = 0, furthest = 0, error = '', currentPlan = null;
function isAvk(){ return ['acenocumarol','warfarina'].includes(state.drug); }
function proc(){ return (window.QXProcedures || []).find(p=>p.id===state.procedureId); }
function clinicalInput(){return {...state,specialProcedure:''};}
function decision(){return QXClinical.managementDecision(clinicalInput());}
function tag(level){return `<span class="risk-tag ${esc(level)}">${esc(labels[level]||level)}</span>`;}
function select(name, label, options, hint='') {return `<div class="field"><label class="field-label" for="${name}">${label}</label><select id="${name}" name="${name}" ${(name==='bleedingRisk'&&proc())||(name==='uCanDelay'&&(state.uPriority==='deferred'||(isAvk()&&state.uPriority==='emergency')))?'disabled':''}><option value="">Seleccionar…</option>${options.map(([v,t])=>`<option value="${esc(v)}" ${String(state[name])===String(v)?'selected':''}>${esc(t)}</option>`).join('')}</select>${hint?`<p class="field-hint">${hint}</p>`:''}</div>`;}
function number(name,label,{min=0,max=200,increment='1',hint='',optional=false}={}) {return `<div class="field"><label class="field-label" for="${name}">${label}${optional?' <span class="field-hint">(opcional)</span>':''}</label><input id="${name}" name="${name}" type="number" inputmode="decimal" min="${min}" max="${max}" step="${increment}" value="${esc(state[name])}">${hint?`<p class="field-hint">${hint}</p>`:''}</div>`;}
function check(name,label,hint=''){return `<label class="check-row"><input type="checkbox" name="${name}" ${state[name]?'checked':''}><span>${label}${hint?`<small>${hint}</small>`:''}</span></label>`;}
function choice(name,value,title,description,disabled=false){return `<label class="choice-card ${String(state[name])===String(value)?'selected':''}" ${disabled?'style="opacity:.5"':''}><input type="radio" name="${name}" value="${value}" ${String(state[name])===String(value)?'checked':''} ${disabled?'disabled':''}><span><h3>${title}</h3><p>${description}</p></span></label>`;}
function riskResult(){const r=QXClinical.thromboticRisk(state);return `<div class="inline-result" id="live-risk">${r.score!==null?`<span class="score-value">${r.score}</span><span class="score-label">CHA₂DS₂-VA<br><small>Escala del consenso de 2025</small></span>`:''}<div>${tag(r.level)}<p>${esc(r.reasons.join(' '))}</p></div></div>`;}
function treatment(){return `<p class="section-title">¿Qué anticoagulante toma el paciente?</p><p class="field-hint">Selecciona el principio activo. Esta versión desarrolla la rama de anticoagulación oral del consenso 2025.</p><div class="choice-grid">${Object.entries(QXClinical.DRUGS).map(([k,d])=>choice('drug',k,d.label,d.family==='avk'?'Antagonista de la vitamina K':'Anticoagulante oral directo')).join('')}</div><div class="section-divider"></div><p class="section-title">¿Es una intervención programada?</p><div class="choice-grid">${choice('urgency','elective','Programada','Permite planificar la retirada y el reinicio.')}${choice('urgency','urgent','Urgente o emergente','Recorrido propio: prioridad, última toma y coagulación.')}</div>${state.urgent?'':`<div class="check-list">${check('antiplatelet','También recibe antiagregación','AAS, clopidogrel, prasugrel o ticagrelor. El plan combinado requiere una valoración adicional.')}${check('multipleAnticoagulants','Recibe más de un anticoagulante','Incluye transiciones de tratamiento.')}</div>`}`;}

function procedureList(){const q=state.query.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const rows=(window.QXProcedures||[]).filter(p=>(!state.specialty||p.specialty===state.specialty)&&(!q||(p.name+' '+p.specialty).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(q)));return `<div class="procedure-meta">${rows.length} ${rows.length===1?'procedimiento':'procedimientos'}${state.query?' encontrados':''}</div><div class="procedure-list" role="group" aria-label="Procedimientos">${rows.length?rows.map(p=>`<button type="button" class="procedure-option ${state.procedureId===p.id?'selected':''}" data-procedure="${esc(p.id)}" aria-pressed="${state.procedureId===p.id}"><span><strong>${esc(p.name)}</strong><small>${esc(p.specialty)}</small></span>${tag(p.risk)}</button>`).join(''):'<p class="summary-empty">No hay coincidencias. Prueba otra búsqueda o introduce la clasificación manual.</p>'}</div>`;}
function procedure(){
const p=proc(),d=decision();
const specialties=[...new Set((window.QXProcedures||[]).map(x=>x.specialty))].sort((a,b)=>a.localeCompare(b,'es'));
return `<p class="section-title">¿Qué procedimiento se va a realizar?</p><div class="form-grid">${select('specialty','Especialidad',specialties.map(x=>[x,x]))}<div class="field"><label class="field-label" for="query">Buscar procedimiento</label><input type="search" id="query" name="query" class="procedure-search" placeholder="Ej. catarata, colonoscopia…" value="${esc(state.query)}"></div></div><div id="procedure-results">${procedureList()}</div><button type="button" class="text-button" data-action="manual">Mi procedimiento no aparece: clasificar manualmente</button>${p||state.manual?`<div class="section-divider"></div><div class="notice info"><strong>${p?esc(p.name):'Clasificación manual'}</strong><p>${p?esc(p.note||'Confirma que la técnica prevista coincide con la descrita en el suplemento de 2025.'):'Clasifica el riesgo según el equipo responsable y el protocolo del procedimiento; el algoritmo calculará la sugerencia.'}</p>${p?`<a class="reference-link" href="${esc(p.sourceUrl||QXProcedures.sourceUrl||'https://doi.org/10.1016/j.recesp.2025.07.008')}#page=${esc(p.sourcePage)}" target="_blank" rel="noopener">${p.sourceType==='article'?'Artículo 2025':'Suplemento 2025'} · página ${esc(p.sourcePage)} ↗</a>`:''}</div><div class="form-grid">${select('bleedingRisk','Riesgo hemorrágico del procedimiento',[['minimal','Mínimo'],['low','Bajo'],['moderate','Moderado'],['high','Alto']])}</div><p class="field-hint">Mínimo: hemorragia mayor cercana al 0%. Bajo y moderado: en torno al 0–2%. Alto: puede alcanzar o superar el 2%. Se conserva la distinción bajo/moderado para los tiempos de la figura 2.</p><div class="notice ${d.route==='review'?'warning':d.route==='minimal'?'success':'info'}" id="management-decision"><span class="eyebrow">SUGERENCIA DEL ALGORITMO</span><strong class="notice-title">${esc(d.title)}</strong><p>${esc(d.text)}</p><p class="field-hint">Se completará con el riesgo trombótico y los datos clínicos de los siguientes pasos.</p></div>`:''}<div class="section-divider"></div><div class="check-list">${check('neuraxial','Incluye anestesia neuroaxial, punción lumbar o catéter epidural','Se deriva a un protocolo específico de Anestesia; no se aplica la tabla general de tiempos.')}</div>`;
}
function thrombosis(){
let details='';
if(state.indication==='af')details=`<div class="check-list">${check('heartFailure','Insuficiencia cardiaca / disfunción ventricular')}${check('hypertension','Hipertensión arterial')}${check('diabetes','Diabetes mellitus')}${check('vascularDisease','Enfermedad vascular','Arteriopatía periférica, cardiopatía isquémica o placa aórtica complicada.')}${check('strokeHistory','Antecedente de ictus o AIT')}${check('systemicEmbolism','Antecedente de embolia sistémica periférica','Puntúa 2 junto al componente de ictus/AIT, sin duplicarlos.')}${check('rheumaticMitral','Valvulopatía reumática mitral')}</div>`;
if(state.indication==='valve')details=`${select('valveType','Tipo y posición de la prótesis',[['mitral','Mecánica mitral'],['aorticOld','Mecánica aórtica antigua (bola enjaulada / disco basculante)'],['aorticBileaflet','Mecánica aórtica bivalva'],['tricuspid','Mecánica tricuspídea / otra posición: valoración individual']])}<div class="check-list">${check('strokeHistory','Antecedente de ictus o AIT')}${check('valveThrombosis','Antecedente de trombosis valvular')}</div>`;
if(state.indication==='vte')details=`${number('vteMonths','Meses desde el último episodio de TEV',{min:0,max:1200,increment:'0.1',hint:'Incluye TVP y embolia pulmonar. Para menos de un mes, introduce una fracción.'})}<div class="check-list">${check('recurrentVte','TEV recurrente')}${check('activeCancer','Cáncer activo')}</div>${state.activeCancer?select('cancerType','Contexto oncológico de la tabla 2',[['highVte','Páncreas, mieloproliferativo, cerebro primario, gástrico o esófago'],['other','Otro tipo / sin determinar: valoración individual']],'La nota del consenso identifica estos contextos como de alto riesgo de TEV.') :''}`;
return `<p class="section-title">¿Cuál es el motivo de anticoagulación?</p><div class="choice-grid">${choice('indication','af','Fibrilación auricular','Escala CHA₂DS₂-VA y antecedentes.')}${choice('indication','valve','Prótesis valvular','Posición, tipo y antecedentes embólicos.')}${choice('indication','vte','Tromboembolia venosa','Tiempo desde el evento y recurrencia.')}${choice('indication','other','Otras indicaciones','Trombofilia, trombos u otros antecedentes de la tabla 2.')}</div>${state.indication?`<div class="section-divider"></div>${number('age','Edad (años)',{min:18,max:120})}${details}${state.strokeHistory&&state.indication!=='vte'?number('strokeMonths','Meses desde el último ictus o AIT',{max:1200,increment:'0.1'}):''}<div class="section-divider"></div><p class="section-title">Otros factores trombóticos</p>${select('thrombophilia','Trombofilia',[['none','No conocida'],['nonsevere','No grave'],['severe','Grave']])}<p class="field-hint">No grave: factor V Leiden o protrombina G20210A en heterocigosis. Grave: homocigosis, doble heterocigosis, déficits de proteína C/S o antitrombina, o defectos múltiples.</p><div class="check-list">${check('antiphospholipidSyndrome','Síndrome antifosfolipídico conocido')}${check('perioperativeStroke','Ictus durante un periodo perioperatorio previo')}${check('recentCardioembolicStroke','Ictus cardioembólico reciente (menos de 3 meses)')}${check('intracardiacThrombus','Trombo intracavitario conocido')}${check('floatingAorticThrombus','Trombo aórtico flotante conocido')}</div>${riskResult()}<div class="check-list">${check('riskConfirmed','He revisado los antecedentes y los datos de riesgo','Las casillas sin marcar se consideran ausentes.')}</div><p class="field-hint">Las categorías de la tabla 2 son de riesgo tromboembólico anual; no representan la probabilidad de trombosis de esta intervención.</p>`:''}`;
}
function clinical(){return `<p class="section-title">Completa los datos que cambian la pauta.</p><div class="form-grid">${isAvk()?number('inr',state.bleedingRisk==='minimal'?'INR previo al procedimiento':'INR aproximadamente 7 días antes',{min:0.1,max:20,increment:'0.1',hint:'El consenso ajusta la retirada al INR. En riesgo mínimo se revisa el INR previo al procedimiento.'}):number('crcl','Aclaramiento de creatinina (mL/min)',{min:0.1,max:250,increment:'any',hint:'Cockcroft–Gault. No introducir automáticamente el FG indexado a 1,73 m².'})}<div class="field"><label class="field-label" for="procedureDate">Fecha de intervención <span class="field-hint">(opcional)</span></label><input type="date" name="procedureDate" id="procedureDate" value="${esc(state.procedureDate)}"><p class="field-hint">Permite mostrar las fechas del calendario. No fija la hora de la última toma.</p></div></div>${isAvk()?`<details><summary class="text-button">Añadir función renal (útil si se valora puente)</summary>${number('crcl','Aclaramiento de creatinina (mL/min)',{min:0.1,max:250,increment:'any',optional:true})}</details>`:`<details id="cg-details" ${state.cgOpen?'open':''}><summary class="text-button">Calcular Cockcroft–Gault</summary><div class="form-grid">${number('cgAge','Edad (años)',{min:18,max:120})}${select('cgSex','Sexo para la fórmula',[['female','Mujer'],['male','Hombre']])}${number('weightKg','Peso (kg)',{min:1,max:500,increment:'0.1'})}${number('creatinine','Creatinina sérica',{min:0.01,max:3000,increment:'any'})}${select('creatinineUnit','Unidad de creatinina',[['mg/dL','mg/dL'],['umol/L','µmol/L']])}</div><p class="field-hint">La fórmula utiliza el peso introducido. Obesidad, caquexia, edema y lesión renal aguda requieren revisar la estimación.</p><button class="button secondary" data-action="cg">Calcular y usar aclaramiento</button></details>`}<div class="section-divider"></div><p class="section-title">Situaciones que requieren revisión individual</p><div class="check-list">${check('renalUnstable','Función renal inestable o lesión renal aguda')}${check('activeBleeding','Hemorragia activa')}${check('severeLiverDisease','Hepatopatía grave')}${check('pregnancy','Embarazo')}${check('bleedingModifiers','Otros factores personales de sangrado','Hemorragia reciente o en procedimientos previos, trombocitopenia, trombopatía, INR lábil u otros factores.')}</div><div class="check-list">${check('clinicalConfirmed','He revisado estos datos y situaciones especiales')}</div><div class="notice info"><strong>El reinicio será siempre condicional.</strong><p>La hemostasia y la ausencia de sangrado deben confirmarse después del procedimiento con el equipo responsable.</p></div>`;}

const urgentTitles = ['Tratamiento','Prioridad y seguridad','Última toma y riñón','Coagulación','Propuesta urgente'];
const urgentSubtitles = ['Fármaco y contexto','Tiempo y situación clínica','Dosis y eliminación','INR o efecto del ACOD','Actuación y reevaluación'];
const safetyQuestions = [
  ['uBleeding','Hemorragia activa'],['uUnstable','Inestabilidad hemodinámica'],
  ['uNeuraxial','Anestesia neuroaxial, punción lumbar o catéter epidural'],
  ['uAntiplatelet','Tratamiento antiagregante concomitante'],['uMultiple','Más de un anticoagulante o transición de tratamiento'],
  ['uLiver','Hepatopatía grave'],['uPregnancy','Embarazo']
];
const triOptions = [['yes','Sí'],['no','No'],['unknown','No se sabe']];
const knownOptions = [['known','Sí, se conoce'],['unknown','No se conoce']];
const priorityLabels = {emergency:'Emergente (<6 h)',urgent:'Urgente (6–24 h)',deferred:'Urgente diferida (>24 h)'};
const triLabels = {yes:'Sí',no:'No',unknown:'No se sabe'};
function urgentBanner(){return `<div class="notice danger urgent-banner" role="note"><strong>Suspender el anticoagulante y activar la valoración hospitalaria.</strong><p>No retrasar la atención por completar este asistente. La propuesta requiere confirmación del equipo responsable.</p></div>`;}
function urgentPriority(){return `<p class="section-title">¿Cuánto puede esperar la intervención?</p><p class="field-hint">Registra la prioridad acordada con el equipo. Una respuesta desconocida se conserva como tal y conduce a revisión.</p><div class="form-grid">${number('age','Edad (años)',{min:18,max:120})}${select('uPriority','Prioridad de la intervención',Object.entries(priorityLabels))}${select('uCanDelay',isAvk()?'¿Puede demorarse al menos 6 horas?':'¿Admite una demora clínicamente viable para reevaluar?',triOptions,isAvk()&&state.uPriority==='emergency'?'En una emergencia de menos de 6 h, la respuesta queda fijada en No. Cambia la prioridad si el equipo confirma otro margen.':state.uPriority==='deferred'?'Una intervención diferida más de 24 h admite una demora para reevaluar. La respuesta queda fijada en Sí; cambia la prioridad si la situación ha cambiado.':isAvk()?'Figura 4: valorar con Cirugía y Anestesia si existen al menos 6 horas de margen.':'Figura 5: cualquier demora clínicamente viable para reevaluar, también dentro de una emergencia de menos de 6 h. No presupone un intervalo suficiente para eliminar el anticoagulante.')}</div><div class="section-divider"></div><p class="section-title">Situaciones que cambian la valoración</p><div class="form-grid urgent-safety">${safetyQuestions.map(([k,label])=>select(k,label,triOptions)).join('')}</div><p class="field-hint">Marca Sí, No o No se sabe en cada apartado. No hay respuestas clínicas preseleccionadas.</p>`;}
function urgentDose(){return `<p class="section-title">Confirma la pauta y la última administración.</p><div class="form-grid">${select('uDoseKnown','¿Se conoce la dosis del anticoagulante?',knownOptions)}${state.uDoseKnown==='known'?number('uDoseMg','Dosis por toma (mg)',{min:0.001,max:10000,increment:'any',hint:'Introduce los mg del principio activo por toma, no el número de comprimidos. No se calcula una dosis de reversión a partir de este dato.'}):''}${select('uLastDoseKnown','¿Se conoce cuándo fue la última toma?',knownOptions)}${state.uLastDoseKnown==='known'?number('uLastDoseHours','Horas desde la última toma',{min:0,max:87600,increment:'any',hint:'Horas transcurridas hasta esta valoración. Se aceptan decimales. 0 significa una toma en este momento.'}):''}</div>${isAvk()?'<div class="notice info"><strong>El siguiente paso solicita el INR actual.</strong><p>Para decidir la vía urgente se necesita un resultado actual; no se utiliza el INR de planificación de una cirugía programada.</p></div>':`<div class="section-divider"></div><p class="section-title">Función renal actual</p><div class="form-grid">${select('uRenalKnown','¿Se conoce el aclaramiento de creatinina?',knownOptions)}${state.uRenalKnown==='known'?number('uCrcl','Aclaramiento de creatinina (mL/min)',{min:0,max:250,increment:'any',hint:'Cockcroft–Gault, sin indexar a 1,73 m². No sustituir automáticamente por el FG del laboratorio.'}):''}${select('uRenalUnstable','¿Hay lesión renal aguda o función renal inestable?',triOptions)}</div><p class="field-hint">Una función renal desconocida o inestable impide asignar una espera segura con una estimación aislada.</p>`}`;}
function urgentCoagulation(){return `<p class="section-title">${isAvk()?'INR actual para decidir la vía del AVK':'Efecto anticoagulante y pruebas disponibles'}</p>${isAvk()?`<div class="form-grid">${select('uInrKnown','¿Se dispone de un INR actual?',knownOptions)}${state.uInrKnown==='known'?number('uInr','INR actual',{min:0.01,max:20,increment:'any',hint:'El punto de corte de la figura 4 es INR <1,5. Un INR exactamente 1,5 no cumple ese criterio.'}):''}</div>`:`<div class="form-grid">${select('uLevelStatus','Nivel específico del anticoagulante',[['known','Disponible'],['pending','Pendiente de resultado'],['unavailable','No disponible']], 'Medición calibrada para el fármaco seleccionado; no confundir con un anti-Xa calibrado para heparina.')}${state.uLevelStatus==='known'?number('uLevel','Nivel específico (ng/mL)',{min:0,max:100000,increment:'any',hint:'Confirma la unidad, la validez y el momento de la muestra. Un nivel bajo antes de la absorción puede no representar el efecto posterior.'}):''}${state.uLevelStatus==='known'?select('uLevelRepresentative','¿La muestra representa el efecto anticoagulante actual?',triOptions,'Confirma con el laboratorio el momento de extracción y absorción y la ausencia de tomas posteriores. Un valor bajo tomado antes del pico no permite excluir un efecto posterior.'):''}${['dabigatran','rivaroxaban'].includes(state.drug)?select('uQualitative',state.drug==='dabigatran'?'Ratio TTPa (paciente/control)':'Ratio TP (paciente/control)',[['unavailable','No disponible'],['within','≤1,2'],['above','>1,2']], 'Prueba orientativa de la figura 5. Un resultado normal no demuestra ausencia de efecto anticoagulante.'):''}</div>${['apixaban','edoxaban'].includes(state.drug)?'<div class="notice warning"><strong>TP y TTPa no excluyen el efecto de este fármaco.</strong><p>En apixabán y edoxabán, el algoritmo no utiliza estas pruebas rutinarias como criterio de ausencia de anticoagulación.</p></div>':''}`}<div class="section-divider"></div><div class="check-list">${check('uConfirmed','He revisado estos datos urgentes y las situaciones especiales','Al cambiar cualquier dato será necesario volver a confirmar la revisión.')}</div><p class="field-hint">Si un dato no se conoce, selecciónalo así: podrás consultar una propuesta que indicará qué requiere valoración individual.</p>`;}
function urgentRows(){
  const knownValue=(status,v,unit='')=>status==='unknown'?'No se conoce':status==='known'&&v!==''&&v!==null&&v!==undefined?`${v}${unit}`:'';
  const rows=[['Tratamiento',QXClinical.DRUGS[state.drug]?.label],['Contexto','Cirugía urgente'],['Prioridad',priorityLabels[state.uPriority]],[isAvk()?'Demora de al menos 6 h':'Demora viable para reevaluar',triLabels[state.uCanDelay]],['Edad',state.age!==''?`${state.age} años`:''],['Dosis por toma',knownValue(state.uDoseKnown,state.uDoseMg,' mg')],['Última toma',knownValue(state.uLastDoseKnown,state.uLastDoseHours,' h antes de la valoración')]];
  if(isAvk())rows.push(['INR actual',knownValue(state.uInrKnown,state.uInr)]);
  else rows.push(['ClCr (Cockcroft–Gault)',knownValue(state.uRenalKnown,state.uCrcl,' mL/min')],['Función renal inestable',triLabels[state.uRenalUnstable]],['Nivel específico',state.uLevelStatus==='known'&&state.uLevel!==''?`${state.uLevel} ng/mL`:state.uLevelStatus==='pending'?'Pendiente':state.uLevelStatus==='unavailable'?'No disponible':'']);
  if(!isAvk()&&state.uLevelStatus==='known')rows.push(['Muestra representativa del efecto actual',triLabels[state.uLevelRepresentative]]);
  if(['dabigatran','rivaroxaban'].includes(state.drug))rows.push([state.drug==='dabigatran'?'Ratio TTPa':'Ratio TP',{within:'≤1,2',above:'>1,2',unavailable:'No disponible'}[state.uQualitative]]);
  rows.push(...safetyQuestions.map(([k,label])=>[label,triLabels[state[k]]]),['Revisión de datos',state.uConfirmed?'Confirmada':'Pendiente']);
  if(step===4)rows.push(['Propuesta',QXUrgent.makePlan(state).title]);
  return rows;
}
function summaryRows(rows){return rows.map(([label,v])=>`<div class="summary-row"><span>${esc(label)}</span><strong class="${v?'summary-value':'summary-empty'}">${esc(v||'Por completar')}</strong></div>`).join('');}
function urgentSummaryContent(full=false){
  const rows=urgentRows(),split=rows.findIndex(([label])=>label===safetyQuestions[0][1]);
  return `<h3 class="summary-title">Recorrido urgente <span class="pill">${Math.min(step+1,5)}/5</span></h3>${full?summaryRows(rows):`${summaryRows(rows.slice(0,split))}<details class="urgent-summary-details" ${step===4?'open':''}><summary>Situaciones especiales y revisión</summary>${summaryRows(rows.slice(split))}</details>`}`;
}
function urgentResult(){
  currentPlan=QXUrgent.makePlan(state);const p=currentPlan;
  return `<div class="result urgent-result"><div class="result-hero ${p.status==='review'?'review':''}"><p class="result-kicker">PROPUESTA URGENTE · CONSENSO 2025</p><h2 class="result-title">${esc(p.title)}</h2><p>${esc(p.decision.text)}</p></div>${p.blockers.length?`<div class="notice danger"><strong>Datos o situaciones que requieren revisión</strong><ul>${p.blockers.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}<h3 class="section-title">Actuación y reevaluación</h3><ol class="timeline">${p.steps.map(s=>`<li class="timeline-item"><span class="timeline-dot"></span><div class="timeline-content"><span class="timeline-label">${esc(s.label)}</span><h3>${esc(s.title)}</h3><p>${esc(s.text)}</p></div></li>`).join('')}</ol><div class="notice warning"><strong>Condiciones para interpretar esta propuesta</strong><ul>${p.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul></div><div class="print-only">${urgentSummaryContent(true)}</div><p class="field-hint"><strong>Trazabilidad:</strong> ${esc(p.source.short)} · ${esc(p.source.detail)}</p><div class="urgent-source-links"><a href="${esc(p.source.url)}" target="_blank" rel="noopener">Consenso 2025 ↗</a><a href="${esc(p.source.idarucizumabUrl)}" target="_blank" rel="noopener">Ficha EMA · idarucizumab ↗</a><a href="${esc(p.source.andexanetUrl)}" target="_blank" rel="noopener">Ficha EMA · andexanet alfa ↗</a></div><div class="form-actions"><button class="button secondary" data-action="copy">Copiar resumen</button><button class="button primary" data-action="print">Imprimir / PDF</button></div></div>`;
}
function urgentTextSummary(){
  const p=currentPlan||QXUrgent.makePlan(state);
  return ['QxApp · Circuito de cirugía urgente · Consenso español 2025',
    'Solución provisional ante la falta de acceso a QxAApp. Derechos de la aplicación original y del contenido de referencia reservados a la SEC. Pendiente de validación clínica independiente.',
    ...urgentRows().map(([label,v])=>`${label}: ${v||'Por completar'}`),p.title,p.decision.text,
    ...p.blockers.map(x=>'Requiere revisión: '+x),...p.steps.map(s=>`${s.label} · ${s.title}. ${s.text}`),...p.warnings,
    `Fuente: ${p.source.short}. ${p.source.detail}. ${p.source.url}`,
    `EMA Praxbind: ${p.source.idarucizumabUrl}`,`EMA Ondexxya: ${p.source.andexanetUrl}`].join('\n\n');
}
function validateUrgent(){
  const answered=(name,values)=>values.includes(state[name]);
  const numeric=(name,min,max=Number.MAX_VALUE,strict=false)=>state[name]!==''&&Number.isFinite(Number(state[name]))&&(strict?Number(state[name])>min:Number(state[name])>=min)&&Number(state[name])<=max;
  if(step===1){
    if(!numeric('age',18,120))return 'Completa una edad adulta de 18 a 120 años.';
    if(!answered('uPriority',['emergency','urgent','deferred']))return 'Selecciona la prioridad de la intervención.';
    if(!answered('uCanDelay',['yes','no','unknown']))return isAvk()?'Indica si la intervención puede demorarse al menos 6 horas.':'Indica si existe una demora clínicamente viable para reevaluar.';
    if(isAvk()&&state.uPriority==='emergency'&&state.uCanDelay!=='no')return 'La prioridad emergente no admite una demora de al menos 6 horas.';
    if(state.uPriority==='deferred'&&state.uCanDelay!=='yes')return 'La prioridad diferida más de 24 horas debe admitir una demora para reevaluar.';
    for(const [key,label] of safetyQuestions)if(!answered(key,['yes','no','unknown']))return `Completa: ${label}. Puedes marcar No se sabe.`;
  }
  if(step===2){
    if(!answered('uDoseKnown',['known','unknown']))return 'Indica si se conoce la dosis.';
    if(state.uDoseKnown==='known'&&!numeric('uDoseMg',0,Number.MAX_VALUE,true))return 'Introduce una dosis en mg mayor que cero.';
    if(!answered('uLastDoseKnown',['known','unknown']))return 'Indica si se conoce la última toma.';
    if(state.uLastDoseKnown==='known'&&!numeric('uLastDoseHours',0))return 'Introduce las horas transcurridas desde la última toma (0 o más).';
    if(!isAvk()){
      if(!answered('uRenalKnown',['known','unknown']))return 'Indica si se conoce el aclaramiento de creatinina.';
      if(state.uRenalKnown==='known'&&!numeric('uCrcl',0,250))return 'Introduce un aclaramiento de creatinina válido (0–250 mL/min).';
      if(!answered('uRenalUnstable',['yes','no','unknown']))return 'Indica si existe función renal inestable o si se desconoce.';
    }
  }
  if(step===3)return QXUrgent.validate(state)[0]||'';
  return '';
}

function dated(day){if(!state.procedureDate)return '';const d=new Date(state.procedureDate+'T12:00:00');if(!Number.isFinite(d.getTime()))return '';d.setDate(d.getDate()+day);return d.toLocaleDateString('es-ES',{day:'numeric',month:'short',year:'numeric'});}
function result(){
if(state.urgent)return urgentResult();
currentPlan=QXClinical.makePlan(clinicalInput());const p=currentPlan,urgent=state.urgent,d=p.decision||decision();
const restartLabel=p.restart.label||(p.restart.hours?(p.restart.hours[0]===0?'En las primeras 24 h':p.restart.hours[0]===p.restart.hours[1]?'A las '+p.restart.hours[0]+' h':p.restart.hours.join('–')+' h'):'Según pauta');
return `<div class="result"><div class="result-hero ${p.status==='review'?'review':''}"><p class="result-kicker">RESULTADO · CONSENSO 2025</p><h2 class="result-title">${urgent?'Vía de valoración urgente':esc(p.title)}</h2><p>${p.status==='ready'?esc(d.text):'Este caso requiere una decisión individual; no se genera un calendario automático.'}</p></div>${p.blockers.length?`<div class="notice danger"><strong>${urgent?'Prioridad asistencial':'Situaciones que requieren revisión'}</strong><ul>${p.blockers.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}${p.status==='ready'?`<div class="plan-cards"><div class="plan-card"><small>${d.route==='minimal'?'AJUSTE DE TOMAS':'ÚLTIMA DOSIS'}</small><strong>${esc(p.lastDoseLabel||(p.lastDoseDay!==null?'Día −'+Math.abs(p.lastDoseDay):'Según tabla 3'))}</strong><span>${p.lastDoseDay!==null?(dated(p.lastDoseDay)||'Respecto al día de la intervención'):'Riesgo hemorrágico mínimo'}</span></div><div class="plan-card"><small>TERAPIA PUENTE</small><strong>${p.bridge.indicated?'Valorar':'No'}</strong><span>${esc(p.bridge.label)}</span></div><div class="plan-card"><small>REINICIO ORIENTATIVO</small><strong>${esc(restartLabel)}</strong><span>Condicionado a hemostasia</span></div></div>${p.lastDoseDay!==null&&p.stopDays!==null?`<div class="notice info"><strong>Cómo leer el calendario</strong><p>La última dosis corresponde al día −${Math.abs(p.lastDoseDay)}. Después quedan <strong>${p.stopDays} días completos</strong> sin el anticoagulante antes del día 0. Las horas y las tomas deben concretarse con el equipo responsable.</p></div>`:''}<h3 class="section-title">Secuencia del plan</h3><ol class="timeline">${p.steps.map(s=>`<li class="timeline-item"><span class="timeline-dot"></span><div class="timeline-content"><span class="timeline-label">${esc(s.label)}</span><h3>${esc(s.title)}</h3><p>${esc(s.text)}</p></div></li>`).join('')}</ol>`:''}<div class="print-only">${summaryContent()}</div><details ${p.bridge.indicated?'open':''}><summary class="text-button">Consideraciones y límites de este resultado</summary><ul class="field-hint">${p.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul></details><p class="field-hint"><strong>Trazabilidad:</strong> ${esc(p.source.short)} · ${esc(p.source.detail)}${proc()?` · Procedimiento: ${proc().sourceType==='article'?'artículo':'suplemento'} 2025, p. ${esc(proc().sourcePage)}`:''}. ${state.manual?'Clasificación del procedimiento introducida manualmente.':''}</p><div class="form-actions"><button class="button secondary" data-action="copy">Copiar resumen</button><button class="button primary" data-action="print">Imprimir / PDF</button></div></div>`;
}
function summaryContent(){if(state.urgent)return urgentSummaryContent();const r=QXClinical.thromboticRisk(state),p=proc();return `<h3 class="summary-title">Tu recorrido <span class="pill">${Math.min(step+1,5)}/5</span></h3>${[['Tratamiento',QXClinical.DRUGS[state.drug]?.label],['Contexto',state.urgency==='urgent'?'Urgente':state.urgency==='elective'?'Programado':''],['Procedimiento',p?.name||(state.manual?'Clasificación manual':'')],['Riesgo hemorrágico',state.bleedingRisk?labels[state.bleedingRisk]:''],['Indicación',indicationLabels[state.indication]],['Riesgo trombótico',r.level!=='unknown'?r.label:''],['Sugerencia',state.bleedingRisk?(step===4?QXClinical.makePlan(clinicalInput()).title:decision().title):''],[isAvk()?'INR previo':'ClCr',isAvk()?(state.inr||''):(state.crcl!==''?(Math.floor(Number(state.crcl)*100)/100)+' mL/min':'')],['Intervención',state.procedureDate?dated(0):'']].map(([l,v])=>`<div class="summary-row"><span>${l}</span><strong class="${v?'summary-value':'summary-empty'}">${esc(v||'Por completar')}</strong></div>`).join('')}<div class="notice info" style="margin-top:20px"><strong>Cada decisión tiene contexto.</strong><p>Puedes volver a un paso anterior. El plan se recalcula al cambiar los datos.</p></div>`;}
function render(focus=false){
  const titles=state.urgent?urgentTitles:electiveTitles,subtitles=state.urgent?urgentSubtitles:electiveSubtitles;
  const pages=state.urgent?[treatment,urgentPriority,urgentDose,urgentCoagulation,urgentResult]:[treatment,procedure,thrombosis,clinical,result];
  $('#steps').innerHTML=titles.map((t,i)=>`<button class="step-link ${step===i?'active':''} ${i<step?'done':''}" data-step="${i}" ${i>furthest?'disabled':''} ${step===i?'aria-current="step"':''}><span class="step-number">${i<step?'✓':String(i+1).padStart(2,'0')}</span><span class="step-copy"><strong>${t}</strong><span>${subtitles[i]}</span></span></button>`).join('');
  $('#summary').innerHTML=summaryContent();
  $('#panel').innerHTML=`<div class="panel-header"><div><p class="eyebrow">PASO ${String(step+1).padStart(2,'0')} DE 05</p><h2 tabindex="-1" id="step-title">${titles[step]}</h2></div><span class="pill">${step===4?'RESULTADO':state.urgent?'VÍA URGENTE':'VALORACIÓN'}</span></div><div class="panel-body">${state.urgent?urgentBanner():''}${pages[step]()}${error?`<p class="error" role="alert">${esc(error)}</p>`:''}${step<4?`<div class="form-actions"><button class="button secondary" data-action="back" ${step===0?'disabled':''}>← Anterior</button><button class="button primary" data-action="next">${step===3?(state.urgent?'Ver propuesta urgente':'Ver plan perioperatorio'):'Continuar'} <span aria-hidden="true">→</span></button></div>`:`<div class="form-actions"><button class="text-button" data-action="back">← Revisar datos</button><button class="text-button" data-action="reset">Empezar otro caso ↺</button></div>`}</div>`;
  if(focus){$('#step-title').focus({preventScroll:true});$('#panel').scrollIntoView({behavior:'smooth',block:'start'});}
}

function validate(){if(step===0){if(!state.drug)return 'Selecciona un anticoagulante.';if(!state.urgency)return 'Indica si la intervención es programada o urgente.';}
if(state.urgent)return validateUrgent();
if(step===1){if(!proc()&&!state.manual)return 'Selecciona un procedimiento o utiliza la clasificación manual.';if(!state.bleedingRisk)return 'Indica el riesgo hemorrágico.';}
if(step===2){if(!state.indication)return 'Selecciona la indicación de anticoagulación.';if(!(Number(state.age)>=18&&Number(state.age)<=120))return 'Completa una edad de 18 a 120 años.';if(state.indication==='valve'&&(!state.valveType||!(Number(state.age)>=18&&Number(state.age)<=120)))return 'Completa el tipo de prótesis y una edad de 18 a 120 años.';if(state.indication==='vte'&&(!(Number(state.age)>=18&&Number(state.age)<=120)))return 'Esta versión se limita a adultos. Completa una edad de 18 a 120 años.';if(state.indication==='vte'&&(state.vteMonths===''||Number(state.vteMonths)<0))return 'Completa los meses desde el último episodio de TEV.';if(state.strokeHistory&&state.indication!=='vte'&&(state.strokeMonths===''||Number(state.strokeMonths)<0))return 'Completa los meses desde el último ictus o AIT.';if(!state.riskConfirmed)return 'Confirma que has revisado los datos de riesgo.';}
if(step===3){if(!state.clinicalConfirmed)return 'Confirma que has revisado los datos y las situaciones especiales.';if(isAvk()&&(state.inr===''||Number(state.inr)<=0||Number(state.inr)>20))return 'Introduce un INR válido.';if(!isAvk()&&(state.crcl===''||Number(state.crcl)<=0||Number(state.crcl)>250))return 'Introduce un aclaramiento de creatinina válido (0–250 mL/min).';}return '';}
function updateInput(e){
  const el=e.target;if(!el.name)return;const old=state[el.name],value=el.type==='checkbox'?el.checked:el.value;
  currentPlan=null;error='';
  if(['drug','urgency'].includes(el.name)&&old!==value){
    const drug=el.name==='drug'?value:state.drug,urgency=el.name==='urgency'?value:state.urgency;
    state={...fresh(),drug,urgency,urgent:urgency==='urgent'};step=0;furthest=0;
  }else state[el.name]=value;
  if(state.urgent){
    if(el.name!=='uConfirmed')state.uConfirmed=false;
    if(el.name==='uPriority'){
      if(isAvk()&&value==='emergency')state.uCanDelay='no';
      else if(value==='deferred')state.uCanDelay='yes';
      else if(old==='deferred'||(isAvk()&&old==='emergency'))state.uCanDelay='';
    }
    if(['uLevelStatus','uLevel','uLastDoseHours','uLastDoseKnown','uDoseKnown','uDoseMg'].includes(el.name)&&old!==value)state.uLevelRepresentative='';
    const clearFields={uDoseKnown:'uDoseMg',uLastDoseKnown:'uLastDoseHours',uRenalKnown:'uCrcl',uInrKnown:'uInr',uLevelStatus:'uLevel'};
    if(clearFields[el.name]&&old!==value)state[clearFields[el.name]]='';
    if(['apixaban','edoxaban'].includes(state.drug))state.uQualitative='unavailable';
  }else{
    if(el.name==='indication'&&old!==value){for(const k of ['strokeHistory','systemicEmbolism','rheumaticMitral','atrialFibrillation','recurrentVte','activeCancer','valveThrombosis'])state[k]=false;state.riskConfirmed=false;}
    if(['age','sex','heartFailure','hypertension','diabetes','vascularDisease','strokeHistory','systemicEmbolism','strokeMonths','rheumaticMitral','valveType','atrialFibrillation','vteMonths','thrombophilia','recurrentVte','activeCancer','antiphospholipidSyndrome','perioperativeStroke','valveThrombosis','intracardiacThrombus','floatingAorticThrombus','recentCardioembolicStroke','cancerType'].includes(el.name))state.riskConfirmed=false;
    if(el.name==='crcl')state.renalCalculated=false;
    if(['age','sex'].includes(el.name)&&state.renalCalculated){state.crcl='';state.renalCalculated=false;state.clinicalConfirmed=false;}
    if(step===3&&el.name!=='clinicalConfirmed')state.clinicalConfirmed=false;
    if(el.name.startsWith('cg')||['weightKg','creatinine','creatinineUnit'].includes(el.name)){state.cgOpen=true;if(state.renalCalculated){state.crcl='';state.renalCalculated=false;state.clinicalConfirmed=false;}}
    if(el.name==='query'){$('#procedure-results').innerHTML=procedureList();return;}
  }
  if(el.type==='number'||el.type==='date'){
    $('#summary').innerHTML=summaryContent();if($('#live-risk'))$('#live-risk').outerHTML=riskResult();
    for(const key of ['riskConfirmed','clinicalConfirmed','uConfirmed']){const checkbox=document.querySelector('[name="'+key+'"]');if(checkbox)checkbox.checked=state[key];}
    const representative=document.querySelector('[name="uLevelRepresentative"]');if(representative)representative.value=state.uLevelRepresentative;
    const oldError=$('#panel .error');if(oldError)oldError.remove();return;
  }
  render();const focusTarget=document.querySelector('[name="'+CSS.escape(el.name)+'"]'+(el.type==='radio'?'[value="'+CSS.escape(el.value)+'"]':''));if(focusTarget)focusTarget.focus({preventScroll:true});
}

function textSummary(){if(state.urgent)return urgentTextSummary();const p=currentPlan||QXClinical.makePlan(clinicalInput());const lines=['QxApp · consenso español 2025','Solución provisional ante la falta de acceso a QxAApp. Derechos de la aplicación original y del contenido de referencia reservados a la SEC. Pendiente de validación clínica independiente.',`Fármaco: ${QXClinical.DRUGS[state.drug]?.label||'—'}`,`Procedimiento: ${proc()?.name||(state.manual?'Clasificación manual':'—')}`,`Indicación: ${indicationLabels[state.indication]||'—'}`,`Riesgo hemorrágico: ${labels[state.bleedingRisk]||'—'}`,`Riesgo trombótico: ${p.risk.label}`,isAvk()?`INR ${state.bleedingRisk==='minimal'?'previo':'~7 días antes'}: ${state.inr||'—'}`:`ClCr: ${state.crcl||'—'} mL/min`,state.procedureDate?`Intervención: ${dated(0)}`:'',p.title,...p.blockers,...p.steps.map(s=>`${s.label} · ${s.title}. ${s.text}`),p.lastDoseDay!==null&&state.procedureDate?`Fecha de última dosis: ${dated(p.lastDoseDay)}`:'',...p.warnings,`Fuente: ${p.source.short}. ${p.source.detail}. ${p.source.url}`];return lines.filter(Boolean).join('\n\n');}
function toast(message){const t=$('#toast');t.textContent=message;t.classList.remove('hide');setTimeout(()=>t.classList.add('hide'),3500);}
document.addEventListener('input',e=>{if(['number','search','date'].includes(e.target.type))updateInput(e);});
document.addEventListener('change',e=>{if(!['number','search','date'].includes(e.target.type))updateInput(e);});
function goForward(target){
  const original=step;
  for(let i=0;i<target;i++){step=i;error=validate();if(error){render(true);return;}}
  step=target;furthest=Math.max(furthest,step);error='';
  if(!state.urgent&&step===3&&original!==3){state.cgAge=state.age||'';state.cgSex=state.sex||state.cgSex||'';state.creatinineUnit=state.creatinineUnit||'mg/dL';}
  render(true);
}
document.addEventListener('click',async e=>{
  const b=e.target.closest('button');if(!b||b.disabled)return;
  if(b.dataset.step!==undefined){
    const target=Number(b.dataset.step);
    if(Number.isInteger(target)&&target>=0&&target<=4&&target<=furthest){
      if(target>step){goForward(target);return;}
      step=target;error='';render(true);
    }
    return;
  }
  if(b.dataset.procedure&&!state.urgent){
    const p=QXProcedures.find(x=>x.id===b.dataset.procedure);
    if(p){state.procedureId=p.id;state.manual=false;state.bleedingRisk=p.risk;state.neuraxial=!!p.neuraxial||/neuroaxial|neuraxial|intrarraqu|punción lumbar|catéter epidural/i.test(p.name);state.clinicalConfirmed=false;currentPlan=null;render();}
    return;
  }
  switch(b.dataset.action){
    case 'sources':$('#sources-modal').showModal();break;
    case 'close-sources':$('#sources-modal').close();break;
    case 'next':goForward(Math.min(4,step+1));break;
    case 'back':step=Math.max(0,step-1);error='';render(true);break;
    case 'manual':state.manual=true;state.procedureId='';state.bleedingRisk='';state.clinicalConfirmed=false;currentPlan=null;render();break;
    case 'reset':if(!state.drug||window.confirm('¿Empezar un nuevo caso y borrar los datos de esta pestaña?')){state=fresh();step=0;furthest=0;error='';currentPlan=null;render(true);}break;
    case 'cg':{
      if((state.age!==''&&Number(state.cgAge)!==Number(state.age))||(state.sex&&state.cgSex!==state.sex)){error='La edad de Cockcroft–Gault debe coincidir con la edad introducida en el paso anterior.';render();return;}
      const n=QXClinical.cockcroftGault({age:state.cgAge,sex:state.cgSex,weightKg:state.weightKg,creatinine:state.creatinine,creatinineUnit:state.creatinineUnit});
      if(n===null){error='Completa edad, sexo, peso, creatinina y unidad con valores válidos.';render();return;}
      state.crcl=n;state.renalCalculated=true;state.clinicalConfirmed=false;state.cgOpen=true;currentPlan=null;render();toast('Aclaramiento calculado. Se utiliza el valor sin redondear.');break;
    }
    case 'print':window.print();break;
    case 'copy':try{await navigator.clipboard.writeText(textSummary());toast('Resumen copiado.');}catch(_){toast('No se pudo acceder al portapapeles. Usa Imprimir / PDF.');}break;
  }
});
$('#sources-modal').addEventListener('click',e=>{if(e.target===$('#sources-modal'))$('#sources-modal').close();});
render();
})();

